function new_pass(){$("#dialog-new-pass").dialog({title:"Nova senha",modal:!0,autoOpen:!0,height:240,width:220,close:function(){location.href="../login.php"},buttons:{Salvar:function(){$("#senha_usu1").val()!=$("#senha_usu2").val()?alert("As senhas não conferem!"):""==$("#senha_usu1").val()?alert("Preencha o campo sennha!"):$.ajax({type:"POST",url:"../inc/ajax_newpass.php",data:"flag=U&id_usu="+$("#id_usu").val()+"&senha_usu1="+$("#senha_usu1").val(),dataType:"json",success:function(a){if(a&&a.ok)$("<div></div>").html("<br><table align='center'><tr><td>Senha alterada com sucesso!</td></tr></table>").dialog({modal:!0,autoOpen:!0,buttons:{Fechar:function(){$(this).dialog("close"),location.href="../index.php"}},title:"Alerta"});else{var e=a&&a.message?a.message:"Erro ao alterar senha.";alert("Erro: "+e+". (Copie esse erro e informe ao administrador)")}}})},Sair:function(){$(this).dialog("close")}}})}$(function(){"1"===$("#valida_show_newpass").val()&&new_pass()});
